// LA FORMATION MÉTIER « consultant » · voir ./types.
//
// Le cycle réel d'une mission : un client arrive avec une demande (on la
// transforme en question clé, en arbre de problèmes et en hypothèses), on
// établit les faits (marché, concurrents, entretiens), puis on conclut (un
// storyline, un atelier qui décide, un plan d'action). Les trois contraintes
// qui traversent les neuf dojos : la confidentialité du client, des hypothèses
// toujours marquées comme telles, et des chiffres toujours reliés à une source.
import { B } from '../bilingual'
import type { Level, Module } from '../curriculum'
import type { Enrichment } from '../enrich/types'
import type { Deepening } from '../deep/types'
import type { TradePack } from './types'

const TINT = '#d946ef'

/* ================================================================== */
/* CITÉ 1 · CADRER LE PROBLÈME DU CLIENT                               */
/* ================================================================== */

